   142	    pub fn register_agent_unique_with_metadata(
   143	        &self,
   144	        requested_id: &str,
   145	        role: &str,
   146	        client_type: Option<&str>,
   147	        protocol_version: Option<i64>,
   148	    ) -> Result<(String, String)> {
   149	        let now = chrono::Utc::now().timestamp();
   150	        let candidates = std::iter::once(requested_id.to_string())
   151	            .chain((2..=99).map(|i| format!("{}-{}", requested_id, i)));
   152	        for candidate in candidates {
   153	            let token = uuid::Uuid::new_v4().to_string();
   154	            let reactivated = self.conn.execute(
   155	                "UPDATE agents
   156	                 SET role = ?2, joined_at = ?3, session_token = ?4, status = 'active', archived_at = NULL,
   157	                     client_type = ?5, protocol_version = ?6
   158	                 WHERE id = ?1 AND status = 'archived'",
   159	                rusqlite::params![candidate, role, now, token, client_type, protocol_version],
   160	            )?;
   161	            if reactivated > 0 {
   162	                return Ok((candidate, token));
   163	            }
   164	
   165	            let inserted = self.conn.execute(
   166	                "INSERT OR IGNORE INTO agents (
   167	                    id, role, joined_at, session_token, status, archived_at, client_type, protocol_version
   168	                 ) VALUES (?1, ?2, ?3, ?4, 'active', NULL, ?5, ?6)",
   169	                rusqlite::params![candidate, role, now, token, client_type, protocol_version],
   170	            )?;
   171	            if inserted > 0 {
   172	                return Ok((candidate, token));
   173	            }
   174	        }
   175	        anyhow::bail!("Too many agents with base ID '{}'", requested_id);
