   798	        // processes from competing for the same agent's messages.
   799	        let lock_dir = workspace.join("locks");
   800	        std::fs::create_dir_all(&lock_dir)?;
   801	        let lock_path = lock_dir.join(format!("{}.receive.lock", agent));
   802	        let lock_file = std::fs::File::create(&lock_path)
   803	            .with_context(|| format!("failed to create lock file: {}", lock_path.display()))?;
   804	        if lock_file.try_lock_exclusive().is_err() {
   805	            bail!(
   806	                "Another `squad receive --wait` is already running for agent '{}'. \
   807	                 Only one receive --wait per agent is allowed. Use `squad receive {}` \
   808	                 (without --wait) for non-blocking polling.",
   809	                agent,
   810	                agent
   811	            );
   812	        }
   813	        // Keep _lock_file alive for the duration of the wait loop (lock released on drop).
   814	        let _lock_guard = lock_file;
   815	
   816	        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(timeout_secs);
   817	        let mut last_heartbeat = std::time::Instant::now();
   818	        loop {
   819	            let store = open_store(&workspace)?;
   820	
   821	            // Re-check for displacement on each poll (~500ms)
   822	            check_session_token(&workspace, &store, agent, session_token.as_deref())?;
   823	
